CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."COMP_PERSONA_PUESTO" ("IDPERSONAL", "IDPUESTO", "NOMBRE", "WAIS", "THERMAN", "SPRANGER", "HERMAN", "CLEAVER", "LIFO", "EXPERIENCIA", "ESCOLARIDAD", "TOTAL") AS 
  SELECT Compatibilidad.IdPersonal, Compatibilidad.IdPuesto, Personal.Nombre, Compatibilidad.Wais, Compatibilidad.Therman, Compatibilidad.Spranger, Compatibilidad.Herman, Compatibilidad.Cleaver, Compatibilidad.LIFO, Compatibilidad.Experiencia, Compatibilidad.Escolaridad, Compatibilidad.Total FROM Compatibilidad INNER JOIN Personal ON Compatibilidad.IdPersonal = Personal.IdPersonal;
